  Exercise(id:"quatre_fr_e42",lessonId:"quatre_fr_l4",question:"Quel connecteur marque une opposition ?",options:["Cependant","Ensuite","Enfin"],correctIndex:0,explanation:"Cependant introduit une opposition ou une nuance."),
