  Exercise(id:"cp1_eps_e1",lessonId:"cp1_eps_l3",question:"Pourquoi s’échauffe-t-on avant un jeu ?",options:["Pour préparer doucement son corps","Pour se salir","Pour retarder les autres"],correctIndex:0,explanation:"L’échauffement prépare le corps à l’activité."),
  Exercise(id:"cp1_eps_e2",lessonId:"cp1_eps_l3",question:"Que faire au signal d’arrêt ?",options:["Continuer à courir","S’arrêter et écouter","Pousser un camarade"],correctIndex:1,explanation:"Le signal indique qu’il faut arrêter l’action et écouter."),
  Exercise(id:"cp1_eps_e3",lessonId:"cp1_eps_l3",question:"Comment jouer avec les autres ?",options:["En poussant","En partageant le jeu","En cachant le ballon"],correctIndex:1,explanation:"Un jeu collectif demande de partager et de respecter les autres."),
  Exercise(id:"cp1_eps_e4",lessonId:"cp1_eps_l3",question:"Que faire si un camarade tombe ?",options:["Se moquer","Le laisser seul","Prévenir l’adulte et l’aider sans danger"],correctIndex:2,explanation:"Il faut prévenir l’adulte et agir avec prudence."),
  Exercise(id:"cp1_art_e1",lessonId:"cp1_art_l3",question:"Quelle forme ressemble à une roue ?",options:["Un cercle","Un triangle","Un carré"],correctIndex:0,explanation:"Une roue a généralement une forme circulaire."),
  Exercise(id:"cp1_art_e2",lessonId:"cp1_art_l3",question:"Que peut-on utiliser pour colorier ?",options:["Une pierre sale","Des crayons de couleur","De la nourriture"],correctIndex:1,explanation:"Les crayons de couleur sont adaptés au dessin."),
  Exercise(id:"cp1_art_e3",lessonId:"cp1_art_l3",question:"Que faire après le dessin ?",options:["Laisser tout par terre","Casser les crayons","Ranger le matériel"],correctIndex:2,explanation:"Ranger protège le matériel et garde la classe propre."),
  Exercise(id:"cp1_art_e4",lessonId:"cp1_art_l3",question:"Quel objet peut-on dessiner avec un rectangle et un triangle ?",options:["Une maison","Une goutte","Une balle"],correctIndex:0,explanation:"Le rectangle peut former les murs et le triangle le toit."),
  Exercise(id:"cp1_civ_e1",lessonId:"cp1_civ_l3",question:"Que dire en arrivant en classe ?",options:["Au revoir","Bonjour","Tais-toi"],correctIndex:1,explanation:"Dire bonjour est une marque de politesse."),
  Exercise(id:"cp1_civ_e2",lessonId:"cp1_civ_l3",question:"Comment utiliser un livre commun ?",options:["Le déchirer","Le cacher","Le lire puis le ranger"],correctIndex:2,explanation:"Le matériel commun doit être respecté et rangé."),
  Exercise(id:"cp1_civ_e3",lessonId:"cp1_civ_l3",question:"Que faire quand un camarade parle ?",options:["L’écouter","Crier plus fort","Se moquer"],correctIndex:0,explanation:"Écouter permet à chacun de s’exprimer."),
  Exercise(id:"cp1_civ_e4",lessonId:"cp1_civ_l3",question:"Si deux élèves se disputent, que faire ?",options:["Frapper","Demander l’aide de l’adulte","Casser le matériel"],correctIndex:1,explanation:"On règle un conflit sans violence et avec l’aide d’un adulte."),
  Exercise(id:"cp2_eps_e1",lessonId:"cp2_eps_l3",question:"Pourquoi respecte-t-on les limites du terrain ?",options:["Pour jouer dans un espace sûr","Pour empêcher les autres de jouer","Pour perdre le ballon"],correctIndex:0,explanation:"Les limites organisent le jeu et réduisent les risques de collision."),
  Exercise(id:"cp2_eps_e2",lessonId:"cp2_eps_l3",question:"Quand faut-il s’arrêter ?",options:["Quand on est fatigué seulement","Au signal convenu","Jamais"],correctIndex:1,explanation:"Le signal commun permet à tous de s’arrêter ensemble."),
  Exercise(id:"cp2_eps_e3",lessonId:"cp2_eps_l3",question:"Après un effort, quel geste est utile ?",options:["Boire de l’eau","Ne plus respirer","Courir sans arrêt"],correctIndex:0,explanation:"Boire de l’eau aide à compenser les pertes liées à l’effort."),
  Exercise(id:"cp2_eps_e4",lessonId:"cp2_eps_l3",question:"Comment gagner correctement ?",options:["En trichant","En insultant l’équipe adverse","En respectant les règles"],correctIndex:2,explanation:"Le fair-play consiste à respecter les règles et les joueurs."),
  Exercise(id:"cp2_art_e1",lessonId:"cp2_art_l3",question:"Que crée-t-on en répétant plusieurs fois un motif ?",options:["Un rythme visuel","Un bruit","Une odeur"],correctIndex:0,explanation:"La répétition des motifs donne un rythme à l’image."),
  Exercise(id:"cp2_art_e2",lessonId:"cp2_art_l3",question:"Quel matériau propre peut être réutilisé ?",options:["Un carton propre","Un déchet coupant","Un produit toxique"],correctIndex:0,explanation:"Le carton propre peut servir à une création artistique."),
  Exercise(id:"cp2_art_e3",lessonId:"cp2_art_l3",question:"Que faut-il faire avant de peindre ?",options:["Renverser l’eau","Préparer et protéger son espace","Mélanger tous les outils au sol"],correctIndex:1,explanation:"Un espace préparé permet de travailler proprement."),
  Exercise(id:"cp2_art_e4",lessonId:"cp2_art_l3",question:"À quoi sert une couleur dans une image ?",options:["À cacher le dessin","À salir la feuille","À donner une ambiance et distinguer les formes"],correctIndex:2,explanation:"Les couleurs aident à organiser et exprimer l’image."),
  Exercise(id:"cp2_civ_e1",lessonId:"cp2_civ_l3",question:"Pourquoi partage-t-on le matériel ?",options:["Parce qu’il sert à plusieurs élèves","Pour le perdre","Pour empêcher le travail"],correctIndex:0,explanation:"Le matériel commun doit être accessible à tous."),
  Exercise(id:"cp2_civ_e2",lessonId:"cp2_civ_l3",question:"Après avoir utilisé un livre, que faire ?",options:["Le déchirer","Le ranger à sa place","Le garder pour soi"],correctIndex:1,explanation:"Ranger permet aux autres élèves de l’utiliser."),
  Exercise(id:"cp2_civ_e3",lessonId:"cp2_civ_l3",question:"Quelle formule est polie pour demander un crayon ?",options:["Donne vite !","C’est à moi !","S’il te plaît, puis-je utiliser ton crayon ?"],correctIndex:2,explanation:"Une demande polie respecte la personne."),
  Exercise(id:"cp2_civ_e4",lessonId:"cp2_civ_l3",question:"Que faire si on abîme un objet commun ?",options:["Le cacher","Prévenir l’enseignant et expliquer","Accuser un autre élève"],correctIndex:1,explanation:"Il faut reconnaître le problème pour pouvoir le réparer."),
  Exercise(id:"ce1_eps_e1",lessonId:"ce1_eps_l3",question:"Avant de passer le ballon, que faut-il regarder ?",options:["Un partenaire disponible","Le ciel seulement","Le sol derrière soi"],correctIndex:0,explanation:"Regarder un partenaire disponible aide à réussir la passe."),
  Exercise(id:"ce1_eps_e2",lessonId:"ce1_eps_l3",question:"Qui veille au respect des règles pendant le jeu ?",options:["Personne","L’arbitre ou l’enseignant","Les spectateurs uniquement"],correctIndex:1,explanation:"L’arbitre ou l’enseignant aide à faire respecter les règles."),
  Exercise(id:"ce1_eps_e3",lessonId:"ce1_eps_l3",question:"Que faire si une douleur apparaît ?",options:["La cacher","Continuer coûte que coûte","S’arrêter et prévenir l’adulte"],correctIndex:2,explanation:"Une douleur doit être signalée pour éviter d’aggraver une blessure."),
  Exercise(id:"ce1_eps_e4",lessonId:"ce1_eps_l3",question:"Quel comportement aide une équipe ?",options:["Encourager et coopérer","Accuser ses partenaires","Refuser toutes les passes"],correctIndex:0,explanation:"La coopération améliore le jeu collectif."),
  Exercise(id:"ce1_art_e1",lessonId:"ce1_art_l3",question:"Une frise alterne cercle, carré, cercle, carré. Quel motif vient ensuite ?",options:["Triangle","Cercle","Étoile"],correctIndex:1,explanation:"L’alternance reprend le cercle après le carré."),
  Exercise(id:"ce1_art_e2",lessonId:"ce1_art_l3",question:"La symétrie signifie que deux parties sont…",options:["Sans rapport","De couleurs obligatoirement différentes","Disposées comme dans un miroir"],correctIndex:2,explanation:"Deux parties symétriques se correspondent par rapport à un axe."),
  Exercise(id:"ce1_art_e3",lessonId:"ce1_art_l3",question:"Dans une image, le fond est…",options:["L’espace derrière les éléments principaux","Le titre seulement","La signature"],correctIndex:0,explanation:"Le fond constitue l’arrière-plan de l’image."),
  Exercise(id:"ce1_art_e4",lessonId:"ce1_art_l3",question:"Comment présenter une création ?",options:["La cacher","Décrire ses choix de formes et de couleurs","La déchirer"],correctIndex:1,explanation:"Expliquer ses choix aide à présenter son travail."),
  Exercise(id:"ce1_civ_e1",lessonId:"ce1_civ_l3",question:"Quel est un droit de l’élève ?",options:["Empêcher les autres d’apprendre","Abîmer les livres","Recevoir un enseignement"],correctIndex:2,explanation:"Chaque enfant a droit à l’éducation."),
  Exercise(id:"ce1_civ_e2",lessonId:"ce1_civ_l3",question:"Quel est un devoir de l’élève ?",options:["Respecter les règles de la classe","Insulter les autres","Détruire le matériel"],correctIndex:0,explanation:"Respecter les règles permet à tous d’apprendre."),
  Exercise(id:"ce1_civ_e3",lessonId:"ce1_civ_l3",question:"Pourquoi les droits doivent-ils être respectés pour tous ?",options:["Pour favoriser seulement les amis","Pour garantir la dignité de chacun","Pour éviter les cours"],correctIndex:1,explanation:"Chaque enfant mérite le respect et la protection."),
  Exercise(id:"ce1_civ_e4",lessonId:"ce1_civ_l3",question:"Que faire devant une injustice ou une violence ?",options:["Répondre par la violence","Se taire toujours","En parler à un adulte de confiance"],correctIndex:2,explanation:"Un adulte de confiance peut aider à protéger l’élève."),
  Exercise(id:"ce2_eps_e1",lessonId:"ce2_eps_l3",question:"Comment commencer un exercice d’endurance ?",options:["Progressivement","En sprintant jusqu’à l’épuisement","Sans échauffement"],correctIndex:0,explanation:"Un effort progressif respecte les capacités du corps."),
  Exercise(id:"ce2_eps_e2",lessonId:"ce2_eps_l3",question:"Que signifie le fair-play ?",options:["Gagner à tout prix","Respecter règles, partenaires et adversaires","Refuser l’arbitre"],correctIndex:1,explanation:"Le fair-play repose sur le respect et l’honnêteté."),
  Exercise(id:"ce2_eps_e3",lessonId:"ce2_eps_l3",question:"Que faire si l’on se sent mal pendant l’effort ?",options:["Accélérer","Ne rien dire","S’arrêter et prévenir l’adulte"],correctIndex:2,explanation:"Il faut interrompre l’effort et signaler le malaise."),
  Exercise(id:"ce2_eps_e4",lessonId:"ce2_eps_l3",question:"Pourquoi accepter une décision d’arbitrage ?",options:["Pour garantir un jeu organisé et équitable","Pour favoriser la tricherie","Pour arrêter toutes les activités"],correctIndex:0,explanation:"Les décisions permettent d’appliquer les mêmes règles à tous."),
  Exercise(id:"ce2_art_e1",lessonId:"ce2_art_l3",question:"Quel contraste oppose le mieux deux valeurs ?",options:["Deux gris identiques","Noir et blanc","Deux formes cachées"],correctIndex:1,explanation:"Le noir et le blanc créent un contraste clair-foncé marqué."),
  Exercise(id:"ce2_art_e2",lessonId:"ce2_art_l3",question:"Un axe de symétrie partage une figure en parties…",options:["Sans relation","Toujours rondes","Qui se correspondent"],correctIndex:2,explanation:"Les deux parties se correspondent comme dans un miroir."),
  Exercise(id:"ce2_art_e3",lessonId:"ce2_art_l3",question:"Quel élément doit attirer l’œil dans une affiche ?",options:["Le sujet principal","Tous les détails au même niveau","Une zone entièrement vide"],correctIndex:0,explanation:"Le sujet principal doit être mis en évidence."),
  Exercise(id:"ce2_art_e4",lessonId:"ce2_art_l3",question:"Pourquoi laisser de l’espace autour d’un dessin ?",options:["Pour perdre la feuille","Pour rendre l’image plus lisible","Pour cacher le sujet"],correctIndex:1,explanation:"L’espace aide à distinguer les éléments de l’image."),
  Exercise(id:"ce2_civ_e1",lessonId:"ce2_civ_l3",question:"Quel exemple représente un bien commun ?",options:["Un jouet personnel","Un vêtement privé","La bibliothèque de l’école"],correctIndex:2,explanation:"La bibliothèque est utilisée par plusieurs élèves."),
  Exercise(id:"ce2_civ_e2",lessonId:"ce2_civ_l3",question:"Comment régler un désaccord ?",options:["Écouter et chercher une solution","Frapper","Insulter"],correctIndex:0,explanation:"Le dialogue aide à résoudre les conflits pacifiquement."),
  Exercise(id:"ce2_civ_e3",lessonId:"ce2_civ_l3",question:"Qui doit protéger les biens communs ?",options:["Seulement le directeur","Tous les utilisateurs","Personne"],correctIndex:1,explanation:"La protection des biens communs est une responsabilité partagée."),
  Exercise(id:"ce2_civ_e4",lessonId:"ce2_civ_l3",question:"Quel geste protège un point d’eau ?",options:["Jeter des déchets dedans","Verser de l’huile","Garder les abords propres"],correctIndex:2,explanation:"La propreté des abords limite la pollution de l’eau."),
  Exercise(id:"cm1_eps_e1",lessonId:"cm1_eps_l3",question:"Quel est le rôle du retour au calme ?",options:["Faire redescendre progressivement l’effort","Augmenter brutalement la vitesse","Remplacer l’échauffement"],correctIndex:0,explanation:"Le retour au calme permet au corps de récupérer progressivement."),
  Exercise(id:"cm1_eps_e2",lessonId:"cm1_eps_l3",question:"Dans une équipe, une bonne communication consiste à…",options:["Crier sur les partenaires","Donner des informations utiles et écouter","Garder toutes les informations"],correctIndex:1,explanation:"Une communication claire facilite la coopération."),
  Exercise(id:"cm1_eps_e3",lessonId:"cm1_eps_l3",question:"Que faire face à une situation dangereuse ?",options:["L’ignorer","Encourager la prise de risque","Arrêter l’activité et prévenir l’adulte"],correctIndex:2,explanation:"La sécurité passe avant le résultat du jeu."),
  Exercise(id:"cm1_eps_e4",lessonId:"cm1_eps_l3",question:"Quel comportement montre le fair-play ?",options:["Reconnaître une faute et respecter l’adversaire","Tricher discrètement","Se moquer du perdant"],correctIndex:0,explanation:"Le fair-play suppose honnêteté et respect."),
  Exercise(id:"cm1_art_e1",lessonId:"cm1_art_l3",question:"Quel principe rend une composition équilibrée ?",options:["Mettre tous les éléments dans un seul coin","Répartir les éléments dans l’espace","Cacher le sujet"],correctIndex:1,explanation:"L’équilibre vient d’une répartition harmonieuse des éléments."),
  Exercise(id:"cm1_art_e2",lessonId:"cm1_art_l3",question:"À quoi sert le contraste ?",options:["À rendre tous les éléments identiques","À supprimer les couleurs","À mettre un élément en évidence"],correctIndex:2,explanation:"Le contraste attire l’attention sur un élément."),
  Exercise(id:"cm1_art_e3",lessonId:"cm1_art_l3",question:"Comment s’inspirer de son environnement ?",options:["Observer puis transformer les formes et motifs","Copier sans réfléchir","Ne rien regarder"],correctIndex:0,explanation:"L’observation nourrit une création personnelle."),
  Exercise(id:"cm1_art_e4",lessonId:"cm1_art_l3",question:"Quel choix améliore la lisibilité d’une affiche ?",options:["Multiplier les textes minuscules","Hiérarchiser titre, image et informations","Mélanger toutes les couleurs"],correctIndex:1,explanation:"Une hiérarchie claire aide à comprendre le message."),
  Exercise(id:"cm1_civ_e1",lessonId:"cm1_civ_l3",question:"Avant de partager une information sur quelqu’un, il faut…",options:["La répéter immédiatement","Ajouter une rumeur","Vérifier les faits"],correctIndex:2,explanation:"Vérifier évite de diffuser de fausses informations."),
  Exercise(id:"cm1_civ_e2",lessonId:"cm1_civ_l3",question:"Quel acte est une responsabilité collective ?",options:["Entretenir un espace commun","Détruire un banc","Exclure un camarade"],correctIndex:0,explanation:"Les espaces communs doivent être entretenus par leurs utilisateurs."),
  Exercise(id:"cm1_civ_e3",lessonId:"cm1_civ_l3",question:"Comment agir face à une personne exclue ?",options:["L’ignorer","L’accueillir et favoriser sa participation","Se moquer"],correctIndex:1,explanation:"L’inclusion permet à chacun de participer."),
  Exercise(id:"cm1_civ_e4",lessonId:"cm1_civ_l3",question:"Pourquoi respecter les règles communes ?",options:["Pour empêcher toute initiative","Pour favoriser seulement un groupe","Pour protéger les droits et la sécurité de tous"],correctIndex:2,explanation:"Les règles communes protègent la vie collective."),
  Exercise(id:"cm2_eps_e1",lessonId:"cm2_eps_l3",question:"Comment améliorer son endurance durablement ?",options:["Augmenter progressivement la durée de l’effort","Faire un effort maximal chaque jour","Éviter tout repos"],correctIndex:0,explanation:"La progression graduelle limite les risques et développe les capacités."),
  Exercise(id:"cm2_eps_e2",lessonId:"cm2_eps_l3",question:"Que signifie l’équité dans une rencontre sportive ?",options:["Favoriser ses amis","Appliquer les règles de manière juste","Changer les règles pendant le match"],correctIndex:1,explanation:"L’équité demande des règles appliquées de façon juste."),
  Exercise(id:"cm2_eps_e3",lessonId:"cm2_eps_l3",question:"Que faire après une blessure ou un choc ?",options:["Reprendre immédiatement","Le cacher","Arrêter et demander l’aide d’un adulte"],correctIndex:2,explanation:"La santé prime et une blessure doit être évaluée."),
  Exercise(id:"cm2_eps_e4",lessonId:"cm2_eps_l3",question:"Pourquoi la tricherie nuit-elle au sport ?",options:["Elle fausse le résultat et détruit la confiance","Elle améliore l’esprit d’équipe","Elle respecte l’adversaire"],correctIndex:0,explanation:"La tricherie rend la compétition injuste."),
  Exercise(id:"cm2_art_e1",lessonId:"cm2_art_l3",question:"Quel élément situe une scène au loin ?",options:["Le premier plan","L’arrière-plan","La signature"],correctIndex:1,explanation:"L’arrière-plan situe les éléments éloignés."),
  Exercise(id:"cm2_art_e2",lessonId:"cm2_art_l3",question:"Quel choix renforce l’expression d’une œuvre ?",options:["L’absence de sujet","Le hasard uniquement","Des couleurs et un cadrage adaptés à l’intention"],correctIndex:2,explanation:"Les choix plastiques soutiennent le message de l’œuvre."),
  Exercise(id:"cm2_art_e3",lessonId:"cm2_art_l3",question:"Pourquoi expliquer son intention artistique ?",options:["Pour faire comprendre le message recherché","Pour imposer une seule interprétation","Pour remplacer l’image"],correctIndex:0,explanation:"L’intention aide le spectateur à comprendre la démarche."),
  Exercise(id:"cm2_art_e4",lessonId:"cm2_art_l3",question:"Quel matériau peut être réutilisé en sécurité ?",options:["Un objet souillé ou coupant","Du papier et du carton propres","Un produit chimique"],correctIndex:1,explanation:"Les matériaux propres et non dangereux peuvent être réemployés."),
  Exercise(id:"cm2_civ_e1",lessonId:"cm2_civ_l3",question:"Quel geste relève de la citoyenneté au quotidien ?",options:["Détériorer un lieu public","Refuser tout dialogue","Respecter les personnes et protéger les biens communs"],correctIndex:2,explanation:"La citoyenneté se manifeste par des actes responsables."),
  Exercise(id:"cm2_civ_e2",lessonId:"cm2_civ_l3",question:"L’égalité de dignité signifie que…",options:["Chaque personne mérite le respect","Seules certaines personnes comptent","Les différences justifient les insultes"],correctIndex:0,explanation:"Toute personne mérite le respect, quelles que soient ses différences."),
